// Renders research/need-router-20261014/analysis/m0/REPORT.md from the results of run.mjs. The numbers in the findings, tables and readings are read from the
// results object (analysis/m0/diagnostics.json, which carries the launch-environment measurement read from analysis/m0/launch-env.json); the prose only
// chooses wording from computed conditions. Not every figure in the report is computed: some Limits paragraphs state design facts (the census size, the TRAIN
// jobs the real pool will have) and the "Not done" list states figures about files and decisions outside the results (the size of the journals that were
// not rescued, the hand-check subsample, the run time; marked [note]). Those are prose, and `run.mjs --check` does not verify them. Pure: no file reads.
import { fmt } from './common.mjs';

const n3 = x => fmt.n(x, 3), n2 = x => fmt.n(x, 2);
const pc = (x, d = 0) => fmt.pct(x, d);
const list = xs => (xs.length ? xs.join(', ') : 'none');
const tick = b => (b ? 'yes' : 'no');
const code = x => `\`${x}\``;
const tbl = (head, rows) => [`| ${head.join(' | ')} |`, `|${head.map(() => '---').join('|')}|`, ...rows.map(r => `| ${r.join(' | ')} |`), ''];
const usd = (x, d = 3) => fmt.usd(x, d);
const thr = x => (typeof x === 'number' ? Math.round(x).toLocaleString('en-US') : String(x));

/** Source lines: repo-relative paths with the first 16 hex of the sha256 recorded in diagnostics.json. JIT stream files are grouped by experiment. */
function sourceLines(paths, ctx) {
  const uniq = [...new Set(paths)].sort();
  const jit = new Map(), other = [];
  for (const p of uniq) { const m = p.match(/^(research\/jit-20261008\/runs\/[^/]+)\/([^/]+)\/results\.jsonl$/); if (m) (jit.get(m[1]) ?? jit.set(m[1], []).get(m[1])).push(m[2]); else other.push(p); }
  const L = ['Sources:'];
  for (const p of other) L.push(`- ${code(p)}${ctx.sha[p] ? ` (sha256 ${code(ctx.sha[p])})` : ''}`);
  for (const [dir, arms] of jit) L.push(`- ${code(`${dir}/<arm>/results.jsonl`)} for ${arms.length} arm${arms.length > 1 ? 's' : ''} (${arms.map(a => a.replace(/^agent-claude-/, 'agent-').replace(/-5-5/g, '')).join(', ')})`);
  return [...L, ''];
}
const jobSources = (r, ids) => r.inputs.jobs.filter(j => !ids || ids.includes(j.id)).flatMap(j => j.sources);
/** A headline entry (d4 / d6): its label, or `unlabelled` (DESIGN §2: more than 30% of a contending mode's dollars imputed) and why. */
const labOf = h => (h.unlabelled ?? h.headlineUnlabelled ? 'unlabelled' : (h.label ?? h.headlineLabel));
const topOfH = h => ((h.unlabelled ?? h.headlineUnlabelled) ? 'unlabelled' : (h.top ?? h.headlineTop));
const headText = h => ((h.unlabelled ?? h.headlineUnlabelled) ? `unlabelled (${h.unlabelled ?? h.headlineUnlabelled})` : `${h.top ?? h.headlineTop} (${h.label ?? h.headlineLabel})`);
/** The D3 groups with both an ex-ante and a post-hoc primary AUC (the arms the primary comparison scores). */
const scoredGroups = d => d.groups.filter(g => g.primary && g.primary.postHoc !== null && g.primary.exAnte !== null);
const gridCell = key => key.replace(/^V=(\S+) N=(\S+) W=(\S+)$/, 'V = $$$1, N = $2, W = $3');   // 'V=1 N=100 W=1V' -> 'V = $1, N = 100, W = 1V'

// ---------------------------------------------------------------------------------------------------------------------------- D0
function secD0(d, ctx) {
  const L = [];
  const p3 = d.primary.find(p => p.k === 3), p5 = d.primary.find(p => p.k === 5);
  const s3 = p3.design.stats, s5 = p5.design.stats, l3 = p3.loco.stats, l5 = p5.loco.stats;
  const trips = d.sensitivities.filter(v => v.design.l8Trips).map(v => `${v.level}, ${v.keys === 'trusted8' ? '8 keys' : '12 keys'}, k = ${v.k} (${v.design.dominant} of ${v.design.queries} queries)`);
  L.push('## D0. NR-knn neighbours under leave-one-cluster-out, and the L8 share', '',
    '**Grade: dev.** Census of 2026-10-14 (14 families at difficulty 3 and 5, example seeds 601-603), no archived rows. **Question:** do the k nearest TRAIN neighbours of a held-out job come from one TRAIN cluster (L8, DESIGN §6)? If they do for 80% or more of held-out jobs, NR-knn is the family-majority baseline under another name and is demoted (§3).', '',
    `**Method.** Standardised euclidean distance over the 8 trusted keys (the metric of ${code('router.knnPredictor')}), one point per census entry (family at d3 or d5, a proxy for a job), r4 and r5 left out (cut from v1). *Design split:* queries are the ${s3.queries} held-out entries (incident, synth, ownerci, r3p at d3 and d5); the pool is the ${d.pool.trainEntries} TRAIN entries (${Object.entries(d.pool.clusterSizes).map(([c, k]) => `${c} ${k}`).join(', ')}); need-qa and the anchor jobs have no census entry (they enter the anchor sensitivity below). *Leave-one-cluster-out:* every non-cut entry is a query against the entries of all other clusters. A query is **dominant** when at least 80% of its k neighbours share a cluster, **single** when all do. **Chance** is the same statistic for k entries drawn uniformly from the same pool, enumerated exactly: a pool that is 12/16 one cluster makes high shares unremarkable.`, '');
  L.push(...tbl(['k', 'split', 'queries', 'dominant', 'single', 'chance dominant', 'mean modal share', 'chance mean share', 'L8'],
    [[3, 'design', p3.design.stats], [5, 'design', p5.design.stats], [3, 'LOCO', l3], [5, 'LOCO', l5]].map(([k, name, s]) => [k, name, s.queries, `${s.dominant} (${pc(s.dominantShare)})`, `${s.single} (${pc(s.singleShare)})`, pc(s.chanceDominantShare), n3(s.meanModalShare), n3(s.chanceMeanShare), s.l8Trips ? '**trips**' : 'does not trip'])));
  L.push('Design split at k = 3, neighbours nearest first (cluster in brackets):', '',
    ...tbl(['held-out entry', 'neighbours', 'modal cluster (share)'], p3.design.jobs.map(j => [code(j.query), j.neighbours.map(x => `${x.id} (${x.cluster})`).join(', '), `${j.modalCluster} (${n2(j.modalShare)})`])));
  const an = d.anchorSensitivity;
  if (an) {
    const a3 = an.primary.find(p => p.k === 3), a5 = an.primary.find(p => p.k === 5);
    L.push(`**With the six anchor jobs.** They have no census entry, so their beds are generated here with the census's own recipe (example seeds 601-603, difficulty 3 and 5; ${code('anchors.mjs')}) and added as ${an.anchors.length} entries: r0-pad, r3-mini and wbed-stage join W, codefix-notests joins codefix, need-qa is a fourth TRAIN cluster and need-constraint a held-out query. The pool is then ${an.pool.trainEntries} TRAIN entries (${Object.entries(an.pool.clusterSizes).map(([c, k]) => `${c} ${k}`).join(', ')}) and the queries ${an.pool.queries.length}. ${a3.design.l8Trips || a5.design.l8Trips ? '**L8 trips.**' : 'L8 still does not trip:'} ${a3.design.dominant} of ${a3.design.queries} queries have one-cluster neighbours at k = 3 (${pc(a3.design.dominantShare)}; ${pc(a3.design.chanceDominantShare)} at chance) and ${a5.design.dominant} of ${a5.design.queries} at k = 5 (${pc(a5.design.dominantShare)}; ${pc(a5.design.chanceDominantShare)} at chance); the plurality cluster is W for ${a3.design.modalClusterCounts.W ?? 0} queries at k = 3 and need-qa, the new cluster, for ${a3.design.modalClusterCounts['need-qa'] ?? 0}. Leave-one-cluster-out over all ${a3.loco.queries} entries: dominance ${pc(a3.loco.dominantShare, 1)} at k = 3 and ${pc(a5.loco.dominantShare, 1)} at k = 5. The anchor beds' versions and module-graph hashes are in the D1 section.`, '');
  }
  L.push('**Reading.**',
    `- L8 ${s3.l8Trips || s5.l8Trips ? '**trips**' : 'does not trip'} on the census in the primary setting (8 trusted keys, census entries): ${s3.dominant} of ${s3.queries} held-out entries have one-cluster neighbours at k = 3 (${pc(s3.dominantShare)}; ${pc(s3.chanceDominantShare)} at chance) and ${s5.dominant} of ${s5.queries} at k = 5 (${pc(s5.dominantShare)}; ${pc(s5.chanceDominantShare)} at chance). The line is 80%. ${trips.length ? `It does trip in ${trips.length} of the ${d.sensitivities.length} sensitivity variants: ${trips.join('; ')}.` : `It trips in none of the ${d.sensitivities.length} sensitivity variants.`}`,
    `- The plurality cluster is W for ${s5.modalClusterCounts.W ?? 0} of ${s5.queries} held-out entries at k = 5 and for ${s3.modalClusterCounts.W ?? 0} of ${s3.queries} at k = 3. Where the share is not dominant the neighbours still lean on W, the largest TRAIN cluster, so NR-knn would mostly pool W's labels. The kinetics and codefix neighbours of synth and ownerci are the d3 and d5 entries of one family each.`,
    `- Across the whole census (leave one cluster out) dominance is ${pc(l3.dominantShare, 1)} at k = 3 and ${pc(l5.dominantShare, 1)} at k = 5 against ${pc(l3.chanceDominantShare, 1)} and ${pc(l5.chanceDominantShare, 1)} at chance: neighbours are no more cluster-pure than a random draw, so the 8 trusted keys do not pull a family's entries together strongly.`, '',
    '**Limits.** Eight held-out entries in the census (ten with the anchors); census entries stand in for jobs; the census pool has 3 clusters and no need-qa (4 clusters with the anchors), where the real pool will have 15 TRAIN jobs. The census says which TRAIN cluster is nearest, not whether its labels transfer. L8 stays a test to run on the real TRAIN jobs before NL2.', '', ...sourceLines(d.sources.map(s => s.path), ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D1
function secD1(d, ctx) {
  const L = [], R = d.router, M = d.maxExample, F = d.withFanOut;
  const tok = id => d.featureRows.find(r => r.id === id)?.tokens, mx = id => d.jobs.find(j => j.id === id)?.tokens;
  const wf10 = d.jobs.filter(j => j.n10.class === 'workflow'), smallestWf10 = wf10.reduce((a, j) => (tok(j.id) < tok(a.id) ? j : a));
  const smallestWf10Max = wf10.reduce((a, j) => (mx(j.id) < mx(a.id) ? j : a));
  const orFan = r => r.orRule.thetaFanItems === '+inf';
  const tableRows = T => [['N = 1', T.n1], ['N = 10', T.n10]].map(([name, t]) => [name, `${t.workflowJobs} of ${t.jobs}`, `${thr(t.tokenThreshold.thetaTokens)} tokens`, n3(t.tokenThreshold.balancedAccuracy), n3(t.tokenThreshold.accuracy), list(t.tokenThreshold.wrong), n3(t.loco.balancedAccuracy), list(t.loco.wrong),
    `${n3(t.trainToHeldout.balancedAccuracy)} (${list(t.trainToHeldout.wrong)})`, `${n3(t.fixedSizeRule.balancedAccuracy)} (${list(t.fixedSizeRule.wrong)})`, `${t.fixedSizeRule.modeAgreement} of ${t.fixedSizeRule.modes}`]);
  const head = ['hypothesis', 'workflow jobs', 'best threshold', 'balanced acc.', 'accuracy', 'errors', 'LOCO bal. acc.', 'LOCO errors', 'TRAIN-fit applied to held-out', 'size rule (class)', 'size rule mode agreement'];
  L.push('## D1. Shortcut audit: does logInputTokens alone reproduce the hypotheses table?', '',
    `**Grade: dev.** The table is the preregistered expectation (PREREG-NEED-V1 §1.1, ${code('prereg/stages.json')}), not a label. **Question:** if one token threshold sorts the ${d.summary.jobs} measured TRAIN and held-out jobs into workflow and no-workflow, the table is a size table in disguise. **Method.** Best single threshold on log10(1 + tokens) by balanced accuracy, ties to the larger threshold (the preregistered tie rule), for the N = 1 and N = 10 class hypotheses; the same fitted leave-one-cluster-out; fitted on TRAIN and applied to the held-out jobs; and the fixed size rule of DESIGN §6 (under 2K direct-H, 2-30K agent-H, over 30K construct-H). Forced, pending, conditional and unmeasured jobs are left out. Two token measures: **router** is ${code('logInputTokens')} as ${code('features.mjs')} computes it (median over example seeds 601-603, here the mean over the census difficulties inside the job band, the six anchor jobs computed from their beds now): the input the router reads. **max-example** is the largest example input over the nine example seeds (${code('stages.json')}), the measure agent-O budgets use.`, '');
  L.push('Token measure: **router** (logInputTokens as the router reads it):', '', ...tbl(head, tableRows(R)), 'Token measure: **max-example** (stages.json maxExampleTokens):', '', ...tbl(head, tableRows(M)));
  L.push('Jobs in token order on the router feature, largest ten (W = hypothesised workflow):', '', `- N = 1: ${R.n1.tokenOrder.slice(-10).join(' < ')}`, `- N = 10: ${R.n10.tokenOrder.slice(-10).join(' < ')}`, '');
  L.push(`**Fan-out and the preregistered OR rule.** H0 is ${code('logInputTokens >= theta_tok OR maxListLength >= theta_fan')}. On the ${F.n1.jobs} jobs with a feature row (router measure), each rule best-fit:`, '',
    ...tbl(['hypothesis', 'rule', 'best fit', 'balanced acc.', 'errors', 'LOCO bal. acc.'],
      [['N = 1', 'n1'], ['N = 10', 'n10']].flatMap(([name, k]) => [
        [name, 'tokens only', `${thr(R[k].tokenThreshold.thetaTokens)} tokens`, n3(R[k].tokenThreshold.balancedAccuracy), list(R[k].tokenThreshold.wrong), n3(R[k].loco.balancedAccuracy)],
        [name, 'fan-out only', `theta_fan ${typeof F[k].fanOutOnly.theta === 'number' ? n2(F[k].fanOutOnly.theta) : F[k].fanOutOnly.theta} (log10)`, n3(F[k].fanOutOnly.balancedAccuracy), list(F[k].fanOutOnly.wrong), 'n/a'],
        [name, 'OR rule (H0)', `${thr(F[k].orRule.thetaTokTokens)} tokens${orFan(F[k]) ? ', fan-out unused' : `, ${F[k].orRule.thetaFanItems} items`}`, n3(F[k].orRule.balancedAccuracy), list(F[k].orRule.wrong), n3(F[k].orRule.loco.balancedAccuracy)]])));
  const padR = tok('r0-pad'), padM = mx('r0-pad'), rowOf = id => d.featureRows.find(r => r.id === id);
  const variants = [R.n1.tokenThreshold, R.n10.tokenThreshold, M.n1.tokenThreshold, M.n10.tokenThreshold, R.n1.trainToHeldout, R.n10.trainToHeldout, M.n1.trainToHeldout, M.n10.trainToHeldout], incidentWrong = variants.filter(v => v.wrong.includes('incident')).length;
  L.push('**Reading.**',
    `- **${R.n1.tokenThreshold.perfect || R.n10.tokenThreshold.perfect ? 'In part.' : 'No.'}** On the router's own feature the best token threshold reaches balanced accuracy ${n3(R.n1.tokenThreshold.balancedAccuracy)} at N = 1 and ${n3(R.n10.tokenThreshold.balancedAccuracy)} at N = 10 and reproduces ${R.n1.tokenThreshold.perfect ? 'N = 1' : R.n10.tokenThreshold.perfect ? 'N = 10' : 'neither column'}. Errors: ${list(R.n1.tokenThreshold.wrong)} at N = 1, ${list(R.n10.tokenThreshold.wrong)} at N = 10. The max-example measure agrees on class accuracy (${n3(M.n1.tokenThreshold.balancedAccuracy)} and ${n3(M.n10.tokenThreshold.balancedAccuracy)}) with errors ${list(M.n1.tokenThreshold.wrong)} and ${list(M.n10.tokenThreshold.wrong)}. The jobs that break a size rule are the ones the table was written to break (a large no-workflow job: ${list(['incident', 'wbed-r6'].filter(id => R.n1.tokenThreshold.wrong.includes(id)))} at N = 1; a padded one: ${list(R.n10.tokenThreshold.wrong.filter(id => id !== 'incident'))} at N = 10).`,
    `- **The table is mostly, not entirely, a size table.** The workflow class sits at the top of the token order, so a size rule is a strong baseline: the DESIGN §6 fixed rule scores balanced accuracy ${n3(R.n1.fixedSizeRule.balancedAccuracy)} at N = 1 and ${n3(R.n10.fixedSizeRule.balancedAccuracy)} at N = 10 on class (${n3(M.n1.fixedSizeRule.balancedAccuracy)} and ${n3(M.n10.fixedSizeRule.balancedAccuracy)} on max-example). The router has to beat it on exactly the jobs listed above. As a mode map the size rule agrees with the hypothesised mode on ${R.n1.fixedSizeRule.modeAgreement} of ${R.n1.fixedSizeRule.modes} jobs (${M.n1.fixedSizeRule.modeAgreement} of ${M.n1.fixedSizeRule.modes} on max-example): the table puts small jobs on direct-H and mid-sized ones on agent-H differently from the 2K and 30K cut points.`,
    `- **r0-pad bites on the router's feature, narrowly, and not on max-example.** On the router feature it holds ${thr(padR)} tokens, ${n2(padR / tok(smallestWf10.id))} times the ${thr(tok(smallestWf10.id))} of ${smallestWf10.id}, the smallest N = 10 workflow job, so no token threshold separates the two and the best one errs on r0-pad. On max-example it holds ${thr(padM)} against ${thr(mx(smallestWf10Max.id))} for ${smallestWf10Max.id} (${n2(padM / mx(smallestWf10Max.id))} times), below it, and a threshold in between gets it right. The margin is thin and depends on which example seeds and census difficulties stand for the job. [I] Check r0-pad's token margin against the smallest workflow job once the generator and the example seeds are final; if the margin should be robust, pad beyond the largest workflow job (${thr(Math.max(...wf10.map(j => tok(j.id))))} tokens on the router feature), under the 100K long-context price tier.`,
    `- **Held-out jobs.** Fitted on TRAIN and applied to the six held-out jobs, the router-feature threshold errs on ${list(R.n1.trainToHeldout.wrong)} at N = 1 and ${list(R.n10.trainToHeldout.wrong)} at N = 10 (balanced accuracy ${n3(R.n1.trainToHeldout.balancedAccuracy)} and ${n3(R.n10.trainToHeldout.balancedAccuracy)}); on max-example ${list(M.n1.trainToHeldout.wrong)} and ${list(M.n10.trainToHeldout.wrong)}. incident (${thr(tok('incident'))} tokens on the router feature, ${thr(mx('incident'))} at its largest example) is the planned counterexample to a size rule: it is wrong in ${incidentWrong} of the ${variants.length} variants above.`,
    `- **Fan-out alone is worse** (balanced accuracy ${n3(F.n1.fanOutOnly.balancedAccuracy)} at N = 1, ${n3(F.n10.fanOutOnly.balancedAccuracy)} at N = 10). The OR rule fitted in sample reaches ${n3(F.n10.orRule.balancedAccuracy)} at N = 10 and ${n3(F.n1.orRule.balancedAccuracy)} at N = 1${orFan(F.n1) ? ' (where it uses no fan-out at all)' : ''}, but leave-one-cluster-out it falls to ${n3(F.n10.orRule.loco.balancedAccuracy)} and ${n3(F.n1.orRule.loco.balancedAccuracy)}: two thresholds fitted on a handful of clusters do not transfer. This is the F12 risk in miniature.`,
    `- The anchor beds change the fan-out arm: ${code('need-r0pad')} has maxListLength ${n2(rowOf('r0-pad')?.maxListLength)} (log10) against ${n2(rowOf('wbed-r0')?.maxListLength)} for wbed-r0, because the padding documents form a list, so under H0 the fan-out arm can fire on r0-pad as well as the token arm.`, '',
    `**Limits.** Expectations, not labels; ${d.summary.jobs} jobs of which ${R.n1.workflowJobs} (N = 1) or ${R.n10.workflowJobs} (N = 10) are in the workflow class; bands without a census point (d1-2 and d4) use the nearest census difficulty or the log-mean of d3 and d5; the anchor beds were still being written when this was first run, so their features are of the files as they stood: each bed's version and the hash of the module graph that produced them are recorded (below), and a later run that finds another hash reports "inputs moved, re-run" rather than drifting silently.`, '',
    ...(d.anchorBeds?.beds ? ['Anchor beds behind the second table (version, files in the module graph, sha256 of the graph, first 16 hex):', '',
      ...tbl(['bed', 'version', 'files', 'graph sha256'], Object.values(d.anchorBeds.beds).map(b => [code(b.bed), b.version ?? 'n/a', b.files, code(b.sha256)]))] : []),
    ...sourceLines(d.sources.map(s => s.path), ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D2
function secD2(d, ctx) {
  const L = [], p = d.primary, f = p.fisher, nv = d.nversion;
  L.push('## D2. Co-failure on the records dev stream', '',
    `**Grade: LEGACY/dev.** Source: the JIT stream ${code('research/jit-20261008/runs/jit-dev-records-1/')} (${p.tasks} paired dev tasks, one draw per mode, K = 1). **Question:** do agent-H and the static B1-Haiku solver fail on the same tasks more often than independence predicts? If so, agreement between modes cannot stand in for a verifier (portfolio-by-disagreement, DESIGN §3 secondary 6). **Method.** Wrong = oracle pass is false (a refusal or timeout counts). Lift = P(both wrong) / (P(A wrong) x P(B wrong)); the p-value is a permutation test of the joint failure rate over tasks (for single-draw data it equals the one-sided Fisher exact test); the interval is a seeded bootstrap over tasks.`, '');
  L.push(...tbl(['', 'static-b1h wrong', 'static-b1h right'], [['agent-H wrong', f.both, f.onlyA], ['agent-H right', f.onlyB, f.neither]]));
  L.push(`P(agent-H wrong) = ${n3(p.pA)}, P(static-b1h wrong) = ${n3(p.pB)}, P(both wrong) = ${n3(p.pBoth)} against ${n3(p.expectedIfIndependent)} if independent: **lift ${n2(p.lift)}**, 95% interval ${fmt.ci(p.liftCI[0], p.liftCI[1])}, permutation p = ${n3(p.pPermutation)} (Fisher ${n3(f.p)}). P(static wrong | agent wrong) = ${n3(p.pBgivenAWrong)}; P(static wrong | agent right) = ${n3(p.pBgivenARight)}.`, '');
  const row = q => [code(q.job), `${q.a} x ${q.b}`, q.tasks, n3(q.pA), n3(q.pB), n3(q.pBoth), n3(q.expectedIfIndependent), n2(q.lift), q.liftCI ? fmt.ci(q.liftCI[0], q.liftCI[1]) : 'n/a', n3(q.pPermutation)];
  const others = d.recordsStreamPairs.filter(q => q.lift !== null && !(q.a === p.a && q.b === p.b));
  L.push('Other pairs with a defined lift (descriptive: pairs from the same stream overlap, and a mode that never fails has no lift):', '',
    ...tbl(['job', 'pair', 'tasks', 'P(A)', 'P(B)', 'P(both)', 'expected', 'lift', '95% interval', 'p'], [...others, ...d.secondary.filter(q => q.lift !== null), ...nv.pairs].map(row)));
  const best = [...nv.pairs].sort((a, b) => b.lift - a.lift)[0];
  L.push('**Reading.**',
    `- **No excess co-failure between agent-H and the static solver on this stream:** lift ${n2(p.lift)}, ${f.both} joint failures of ${p.tasks} against ${n2(p.expectedIfIndependent * p.tasks)} expected. This is absence of evidence at n = ${p.tasks}: the interval's upper end is ${n2(p.liftCI[1])}, so a doubling of co-failure is not excluded.`,
    `- Elsewhere the lift is mostly above 1 (${d.summary.pairsLiftAbove1} of ${d.summary.pairsTotal} pairs with a defined lift, median ${n2(d.summary.medianLift)}), but only ${d.summary.pairsSignificant} reach p <= 0.05 and the pairs overlap. The clearest are among the compiled solvers of the committed N-version probe (${code('research/jit-20261008/nversion-records-dev.json')}): the strongest, ${best.a} x ${best.b}, has lift ${n2(best.lift)} (p ${n3(best.pPermutation)}) and P(second wrong | first wrong) = ${n2(best.pBgivenAWrong)} against ${n2(best.pBgivenARight)} when the first is right. The probe itself reports ${nv.unanimous.n} unanimous tasks of which ${nv.unanimous.n - nv.unanimous.pass} was wrong in every solver: a common-mode failure. Those failures mix wrong answers with refusals (deopts), so they say less about wrongness alone.`,
    '- Consequence for the plan: agreement of two modes cannot be assumed to flag a wrong answer. Any use of disagreement as a verifier must be measured per pair on the label matrix (DESIGN §3 secondary 6), not inferred from independence. Bounded by one dev stream.', '',
    ...sourceLines([...jobSources(ctx.r, ['jit-dev-records-1', 'p1-records', 'c0-dev-records', 'c0-dev-codefix', 'jit-dev-kinetics-1', 'jit-r0-kinetics', 'jit-r0-records']), nv.source.path], ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D3
function secD3(d, ctx) {
  const L = [], s = d.summary, pr = s.primary, sv = s.selfVerdict;
  const scored = scoredGroups(d);
  const keysOf = fam => [...new Set(d.groups.filter(g => g.family === fam && g.structureKeysThatVary).flatMap(g => g.structureKeysThatVary))];
  const tok = s.exAnteBySignal.logInputTokens, cost = s.postHocBySignal.logCost;
  const p1a = d.groups.find(g => g.job === 'p1-records' && g.mode === 'agent-H' && g.byDifficulty?.[3] && g.byDifficulty?.[4]);
  L.push('## D3. Ex-ante against post-hoc signals', '',
    `**Grade: LEGACY/dev.** **Question** (Dekoninck, Baader and Vechev): do deployable post-hoc signals (schema validity, turns, cost) predict the oracle better than the structure features? **Method.** One delivered answer per row (timeouts and crashes are free post-hoc signals and are left out); target = oracle pass. Ex-ante: the 8 trusted features of the regenerated task (task hashes checked against the archive: ${tick(d.hashesChecked)}, ${d.taskCount} tasks). Post-hoc: schema validity (reconstructed from the oracle's own schema check, the only stored trace of one; a row without oracle details has none), turns, tool uses, run cost, output tokens, workflow node calls and escalations, the workflow's own verdict; never score, oracle details beyond that schema flag, or the pass flag. A signal is scored only where every row of the arm records it (a missing value is not a zero). Wall time is excluded (confounded by concurrency, DESIGN §2). Scores are parameter-free with the direction fixed in advance (more input, a longer list, a costlier run, more turns, an invalid schema or a failed verdict predicts a failure); AUC is computed **within difficulty**, because the d3 and d4 mixes differ in size and in pass rate. Primary pair per arm: AUC of -logInputTokens against AUC of -logCost, with a seeded task bootstrap of the difference. An arm needs at least 4 passes and 4 failures among delivered answers: ${s.groupsScored} of ${s.groups} scoreable arm-by-job groups qualify. **Not scored:** ${s.groupsExcluded} further groups (${list(s.excludedModes.map(code))}, ${s.groupsTotal} groups in all): ${[...new Set(d.excluded.map(x => x.reason))].join('; ')}.`, '');
  L.push(...tbl(['job', 'arm', 'rows', 'pass/fail', 'ex-ante AUC (tokens)', 'post-hoc AUC (cost)', 'difference', '95% interval', 'structure keys that vary'],
    scored.map(g => [code(g.job), g.mode, g.rows, `${g.passes}/${g.fails}`, n2(g.primary.exAnte), n2(g.primary.postHoc), g.primary.delta >= 0 ? `+${n2(g.primary.delta)}` : n2(g.primary.delta), g.primary.ci ? fmt.ci(g.primary.ci[0], g.primary.ci[1]) : 'n/a', g.structureKeysThatVary.length])));
  const roll = (title, o) => [title, '', ...tbl(['signal', 'arms', 'median AUC', 'above 0.5', 'below 0.5'], Object.entries(o).map(([k, v]) => [code(k), v.groups, n2(v.median), v.above, v.below]))];
  L.push(...roll('Every pre-specified post-hoc signal, over the arms where it varies (0.5 = no information; below 0.5 = the pre-specified direction was wrong):', s.postHocBySignal), ...roll('Ex-ante features, same arms:', s.exAnteBySignal));
  L.push('The workflows\' own verdict against the oracle (a first F11-style count; F11 needs at least 10 oracle failures per lineage, and no arm here has that many):', '',
    ...tbl(['job', 'arm', 'delivered', 'oracle failures', 'verdict pass on a failure', 'oracle passes', 'verdict not-pass on a pass'],
      d.groups.filter(g => g.selfVerdict && g.selfVerdict.oracleFail > 0).map(g => [code(g.job), g.mode, g.selfVerdict.delivered, g.selfVerdict.oracleFail, `${g.selfVerdict.falsePass} (${pc(g.selfVerdict.falsePassRate)})`, g.selfVerdict.oraclePass, g.selfVerdict.falseFail])));
  L.push('**Reading.**',
    `- **Neither family discriminates reliably within a family and difficulty at these sizes.** Median AUC ${n2(pr.medianAucExAnte)} for the ex-ante token score and ${n2(pr.medianAucPostHoc)} for the post-hoc cost score. The post-hoc score is ahead in ${pr.postHocBetter} of ${scored.length} arms, but its interval excludes zero in ${pr.postHocBetterCIExcludesZero} (and the ex-ante score's in ${pr.exAnteBetterCIExcludesZero}). The cost direction was right in ${cost.above} arms and wrong in ${cost.below}. [I] Cost in these runs probably tracks input size more than failure.`,
    `- Within one family the structure features hardly vary: in the records arms ${keysOf('records').length === 1 ? `only ${code(keysOf('records')[0])}` : list(keysOf('records').map(code))} differs between tasks; in kinetics ${keysOf('kinetics').length} keys do. The ex-ante token score points the wrong way in ${tok.below} of ${tok.groups} arms${p1a ? ` (for P1's agent-H the d4 inputs are larger than the d3 ones, ${n2(10 ** p1a.byDifficulty[4].meanLogInputTokens / 10 ** p1a.byDifficulty[3].meanLogInputTokens)} times, and pass ${p1a.byDifficulty[4].passes} of ${p1a.byDifficulty[4].rows} against ${p1a.byDifficulty[3].passes} of ${p1a.byDifficulty[3].rows} at d3)` : ''}. The router decides per job, so this does not test it; it says the instance-level gap Dekoninck et al. describe is not visible in this archive.`,
    `- **The one clear post-hoc finding is a negative one:** across ${sv.arms} workflow arms the workflow's own verdict was "pass" on ${sv.falsePass} of ${sv.oracleFailures} oracle failures (${pc(sv.falsePassRate)}; one-sided 95% lower bound ${n2(sv.lowerBound95)} on the false-pass rate). That includes the five C0-dev failures whose run verdict was "pass" (\`research/construction-20261006/REPORT-dev.md\`) and one P1 hand-workflow failure. It is why DESIGN §2 withholds self-check credit until a lineage's false-pass rate is measured (F11).`,
    '- A cascade needs post-hoc estimates much better than ex-ante ones (Dekoninck et al.). Nothing here shows that for deployable signals; the only trustworthy post-hoc signal would be an executable check independent of the workflow itself, and the archive has none.', '',
    `${s.postHocPartlyRecorded.length ? `Signals recorded for only some rows of an arm, left out of that arm instead of scored as zero: ${s.postHocPartlyRecorded.map(x => `${x.job} ${x.mode} ${x.signal} (${x.missing} of ${x.of} rows lack it)`).join('; ')}.\n\n` : ''}**Limits.** ${Math.min(...scored.map(g => g.rowsDelivered))} to ${Math.max(...scored.map(g => g.rowsDelivered))} delivered answers per scored arm, dev seeds, two difficulty levels, one draw per task in the JIT streams; intervals are wide and not corrected for the number of arms. The JIT and static arms (${s.groupsExcluded} groups) are not scored at all, so the answer holds for direct calls, agents and hand-written, Foundry and script workflows only. Every task is regenerated from its task key only after the seed ledger allows it (${code('assertArchivedSeeds')}: a seed reserved for another purpose, in an unspent test range or in the held-out range is refused).`, '',
    ...sourceLines(jobSources(ctx.r), ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D4
function secD4(d, ctx) {
  const L = [], s = d.summary;
  const rec = d.jobs.filter(j => j.oracle === 'records'), kin = d.jobs.filter(j => j.oracle === 'kinetics');
  const gainRec = rec.map(j => j.rowFlips.gainedShare);
  const frag = d.jobs.filter(j => j.grid.fragile);
  const live = d.jobs.filter(j => !j.labelSets.today.vacuous);
  const p1 = d.jobs.find(j => j.job === 'p1-records');
  const auth = ctx.r.inputs.p1Authoring;
  const unlabelledLines = d.jobs.flatMap(j => [['L_today', j.grid], ['L_ceiling', j.ceiling?.grid]].filter(([, g]) => g && g.unlabelled > 0)
    .map(([name, g]) => `- ${code(j.job)} ${name}: ${g.unlabelled} of ${g.cells} cells unlabelled (${Object.entries(g.unlabelledReasons).map(([r, n]) => `${n} x ${r}`).join('; ')}).`));
  L.push('## D4. Tolerance fragility on archived records and kinetics rows', '',
    `**Grade: LEGACY/dev.** **Question:** an oracle's numeric tolerance is a hidden slider. Halve it, double it: how many pass flags move, and does the NEED label move? **Method.** Each row's pass flag is recomputed from the oracle's own recorded details at tolerance x 0.5 and x 2 (records: field accuracy >= 0.97, pair F1 >= 0.95 and entity slack 2% become 0.985 / 0.975 / 1% and 0.94 / 0.90 / 4%; kinetics: relative error <= 0.10 on Vmax and Km becomes 0.05 and 0.20, with the evaluator-health check scaled too). The nominal recompute must reproduce every archived flag: ${s.nominalReproduced ? `it does, all ${s.rowsTotal} rows` : '**it does not**'}. Labels come from ${code('metrics.needLabels')} recomputed at each factor over the whole 27-cell grid (V in {0.1, 1, 10}, N in {1, 10, 100}, W in {V, 0, 10V}), which is the preregistered fragility definition of ${code('metrics.fragility')}: point labels with the 0.03 acceptable set and LEGACY mode classes (hand and Foundry workflows, static solvers and JIT count as workflow; direct calls and agents as no-workflow). **Two label sets** (DESIGN §2): **L_today** (the table's label columns) keeps the workflows written by the cheap builder, Haiku, and **L_ceiling** adds the rest. The rule is one field, the author of the workflow (${code('legacy.mjs')} ${code('builder')}): ${Object.entries(ctx.r.inputs.ceilingRule?.byBuilder ?? {}).map(([b, ms]) => `${b}: ${ms.join(', ')}`).join('; ')}. The ceiling arms are the P1 hand workflow (an Opus agent wrote it after studying the family), the Opus-built C0 workflows, the Opus-compiled JIT arm and, by the same rule, the Sonnet-compiled one (a decision: DESIGN §2 names Haiku as today's builder and admits only build-O and the references beyond it). Every build is charged as a build row${auth ? `, the hand workflow's authoring included (${usd(auth.usd, 2)}${auth.lowerBound ? ' at least' : ''}, to each hand mode in full)` : ''}. A job whose L_today has no workflow-class mode is **vacuous**: its label can only be no-workflow (${list(s.vacuousJobs.map(code))}). **Unlabelled cells** (DESIGN §2 "one cost meter": a cell where a mode that could reach the acceptable set has more than 30% of its per-task dollars imputed) carry no label and no best mode: they are shown as unlabelled with the reason, counted per job, and left out of the label counts, the flip counts, the best-mode-change counts and the fragility test.`, '');
  L.push(...tbl(['job', 'oracle', 'rows', 'passes lost at x0.5', 'failures gained at x2', 'L_today label x0.5 / x1 / x2', 'L_today best mode x0.5 / x1 / x2', 'unlabelled cells (L_today / L_ceiling)', 'label-flip cells', 'best-mode-change cells', 'fragile', 'L_ceiling label / best mode (x1); flip cells'],
    d.jobs.map(j => [code(j.job), j.oracle, j.rows, `${j.rowFlips.lostAtHalf} of ${j.rowFlips.passes} (${pc(j.rowFlips.lostShare, 1)})`, `${j.rowFlips.gainedAtDouble} of ${j.rowFlips.fails} (${pc(j.rowFlips.gainedShare, 1)})`,
      `${['0.5', '1', '2'].map(f => labOf(j.headline[f])).join(' / ')}${j.labelSets.today.vacuous ? ' (vacuous)' : ''}`, ['0.5', '1', '2'].map(f => topOfH(j.headline[f])).join(' / '),
      `${j.grid.unlabelled} of ${j.grid.cells} / ${j.ceiling ? `${j.ceiling.grid.unlabelled} of ${j.ceiling.grid.cells}` : 'same'}`,
      `${j.grid.flipped} of ${j.grid.labelled}`, `${j.grid.topChangedCells} of ${j.grid.labelled}`, tick(j.grid.fragile),
      j.ceiling ? `${labOf(j.ceiling.headline['1'])} / ${topOfH(j.ceiling.headline['1'])}; ${j.ceiling.grid.flipped} of ${j.ceiling.grid.labelled}` : 'same as L_today'])));
  if (unlabelledLines.length) L.push(`Why cells are unlabelled (${s.unlabelledCells} of ${s.cells} job-by-cell cells in L_today):`, '', ...unlabelledLines, '');
  L.push('Pass rate per mode at x0.5 / x1 (archived) / x2, for the two jobs with the largest movement:', '');
  for (const id of ['jit-dev-records-1', 'jit-r0-records']) {
    const j = d.jobs.find(x => x.job === id);
    if (j) L.push(...tbl(['job: mode', 'x0.5', 'x1', 'x2'], Object.entries(j.passRates).map(([m, r]) => [`${id}: ${m}`, n2(r.half), n2(r.nominal), n2(r.double)])));
  }
  if (p1?.ceiling) {
    const u = p1.ceiling.headline['1'].u, wf = p1.ceiling.workflowCells, h1 = p1.ceiling.headline['1'];
    L.push(`The P1 hand workflow, authoring charged (utility in success-equivalents per task at the headline cell V = $1, W = V, N = 10${h1.unlabelled ? `, which is **unlabelled** in L_ceiling (${h1.unlabelled}): the utilities are shown, no label is claimed from them` : ''}):`, '',
      ...tbl(['mode', 'utility', 'note'], Object.entries(u).sort((a, b) => b[1] - a[1]).map(([m, x]) => [m, n3(x), m.startsWith('hand') ? `build ${usd(auth?.usd, 2)} / N = ${10} charged` : ''])),
      `L_ceiling labels ${p1.ceiling.grid.labelled} of ${p1.ceiling.grid.cells} cells (${p1.ceiling.grid.unlabelled} are unlabelled): workflow in ${p1.ceiling.labelCounts.workflow}${wf.length ? ` (${wf.map(gridCell).join('; ')})` : ''}, no-workflow in ${p1.ceiling.labelCounts['no-workflow']} and either in ${p1.ceiling.labelCounts.either}.`, '');
  }
  const maxGain = d.jobs.reduce((a, j) => (j.rowFlips.gainedShare > a.rowFlips.gainedShare ? j : a), d.jobs[0]);
  const kFails = kin.reduce((a, j) => a + j.rowFlips.fails, 0), kExcl = kin.reduce((a, j) => a + (j.failuresWithWrongExclusion ?? 0), 0);
  L.push('**Reading.**',
    `- **The pass rates move a lot; the labels mostly do not.** Doubling the tolerance turns ${s.gainedAtDouble} failing rows into passes (${pc(Math.min(...gainRec))} to ${pc(Math.max(...gainRec))} of all failures in the records jobs, ${pc(maxGain.rowFlips.gainedShare)} in ${code(maxGain.job)}); halving it costs ${s.lostAtHalf} passes. Records failures are near misses by field accuracy: the ${d.recordsMismatches.failingAnswers} failing answers with recorded details carry ${d.recordsMismatches.recordedMismatches} recorded field mismatches (at most 12 per answer), ${pc(d.recordsMismatches.topFieldShare)} of them in ${code(d.recordsMismatches.topField)}, not wholesale errors. Kinetics barely moves: ${kExcl} of its ${kFails} failures are a wrong exclusion set, which no tolerance repairs.`,
    `- ${frag.length} of the ${live.length} jobs with a workflow arm in L_today are fragile there by the preregistered definition (a NEED label flips at some factor and cell): ${list(s.fragileJobs)}${frag.length ? `. ${frag.map(j => `${code(j.job)} (${j.modes.filter(m => j.labelSets.today.modes.includes(m)).join(', ')}) flips in ${j.grid.flipped} of ${j.grid.labelled} labelled cells`).join('; ')}: its modes are close in utility, so a changed tolerance moves the label` : ''}. The other ${d.jobs.length - live.length} (${list(s.vacuousJobs.map(code))}) are vacuous in L_today and can say nothing about need there.${s.ceilingFragileJobs.length ? ` In L_ceiling ${list(s.ceilingFragileJobs.map(code))} ${s.ceilingFragileJobs.length > 1 ? 'are' : 'is'} fragile.` : ''}`,
    `- The best **mode** changes more often than the class: in ${s.topChangedCells} of ${s.labelledCells} labelled job-by-cell combinations (${list(s.jobsWithTopChange)}), because several modes sit within a few points of each other. Mode accuracy is the weaker metric for this reason; the class label and the utilities are the primary ones. ${s.unlabelledCells} of the ${s.cells} combinations are unlabelled and not in that count (${list(Object.entries(s.unlabelledByJob).filter(([, v]) => v.today > 0).map(([j, v]) => `${j} ${v.today}`))}).`,
    ...(p1?.ceiling ? [`- **P1 needs its build cost, and its labels rest on imputed dollars.** With the authoring cost left out (as an earlier version of this report had it), the hand workflow looked like a clear win: it passed ${pc(p1.passRates['hand-H'].nominal)} of its trials, and at the headline cell its utility would be ${n2(p1.ceiling.headline['1'].u['hand-H'] + auth.usd / 10)} against ${n2(p1.ceiling.headline['1'].u['agent-H'])} for agent-H, a workflow label with hand-H best (an earlier version of this report said so, because the legacy registry marked the hand modes \`prebuilt\`, which switches off the guard against a built mode with no build row). Charged the ${usd(auth.usd, 2)}${auth.lowerBound ? ' (a lower bound)' : ''} it took to write, the hand workflow costs ${n2(auth.usd / 10)} success-equivalents per task at N = 10 (hand-H utility ${n2(p1.ceiling.headline['1'].u['hand-H'])}). **P1's headline cell is then ${p1.ceiling.headline['1'].unlabelled ? `unlabelled: ${p1.ceiling.headline['1'].unlabelled}` : `${p1.ceiling.headline['1'].label}, ${p1.ceiling.headline['1'].top} best`}** in L_ceiling${p1.headline['1'].unlabelled ? ` and in L_today (${p1.headline['1'].unlabelled})` : ''}: a mode that could reach the acceptable set has more than 30% of its per-task dollars imputed (P1's direct calls that timed out are charged at the $1 per-call bound, never at $0), and DESIGN §2 leaves such a cell without a label. ${p1.ceiling.grid.labelled} of ${p1.ceiling.grid.cells} cells carry an L_ceiling label (workflow in ${p1.ceiling.labelCounts.workflow}) and ${p1.labelSets.today.vacuous ? `L_today is vacuous with ${p1.grid.unlabelled} of ${p1.grid.cells} cells unlabelled` : `${p1.grid.unlabelled} of ${p1.grid.cells} L_today cells are unlabelled`}, so P1 contributes no workflow label to anything built on L_today and no headline label to either set.`] : []),
    '- The recompute is cheap and deterministic; it belongs on every job whose oracle has a numeric tolerance before its label is used.', '',
    `**Limits.** Records and kinetics only (the other families have exact oracles); ${p1?.reproduction.unrecomputable ?? 0} P1 rows (timeouts, no oracle details) keep their nominal flag; the class assigned to JIT modes is an assumption; the P1 authoring cost is a lower bound (the Opus agent's own time is unpriced) and is charged in full to each hand mode, which assumes a user deploys one of them; every workflow not written by Haiku is a ceiling arm (wf-O and script-O as the analogue of build-O, jit-OH with its Opus compiler, jit-SH with its Sonnet compiler by the same rule, which is a decision and not a measurement), which the archived C0 report did not do. Stream rows whose cost was not observed are imputed to the arm's per-task bound (inputs notes), and a label that rests on such dollars is left unlabelled, not reported.`, '',
    ...sourceLines(jobSources(ctx.r, d.jobs.map(j => j.job)), ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D5
function secD5(d, ctx) {
  const L = [], c = d.corpus, b = d.e8AndRunbook, any = c.classes.any;
  const allBelow = ['human', 'wait', 'schedule', 'effects'].every(k => c.classes[k].recall.rate < 0.9);
  const e8Sched = b.e8.typed?.schedule;
  const e8NoSched = e8Sched && e8Sched.evidence.length === 0;
  const nd = id => (b[id].typedNotDeclared ?? []).map(x => x.class);
  L.push('## D5. RX6-lite: guard recall', '',
    `**Grade: dev.** **Question:** the hard guard forces the workflow class on a typed requirement; word cues only raise "ask the user" (DESIGN §3 Stage 0). How well do the cues find the requirements that are really there? Under 0.9 recall the guard asks instead of inferring. **Method.** Part A: the ${c.items} corpus items whose description is the platform's own (provenance ${code('original')}; the ${c.provenanceCounts.written} ${code('written')} descriptions leak graph phrasing and the ${c.provenanceCounts['recovered-by-model']} model-recovered ones are model text, which RX6 excludes). Declared truth comes from each item's graph: human = a human step; wait = a wait node; schedule = a schedule trigger; effects = a write or external effect. Cues are the ones in code (${code('REQUIREMENT_LIBRARY')} and ${code('shapeOf')} words) mapped to classes as: human = ${d.cueMap.human.replace('|', 'or')}; wait = ${d.cueMap.wait.replace('|', 'or')}; schedule = ${d.cueMap.schedule}; effects = ${d.cueMap.effects.replaceAll('|', 'or')}. Part B: E8 and runbook.`, '');
  L.push(`**Part A, ${c.items} corpus descriptions (cue guard against graph truth):**`, '',
    ...tbl(['class', 'graph-positive items', 'cue fires', 'true positives', 'recall [Wilson 95%]', 'precision [Wilson 95%]', 'guard (0.9 rule)'],
      ['human', 'wait', 'schedule', 'effects', 'any'].map(k => [k === 'any' ? '**any of the four**' : k, `${c.classes[k].truthPositives} (${pc(c.classes[k].baseRate)})`, c.classes[k].cueFires, c.classes[k].truePositives, `${n3(c.classes[k].recall.rate)} ${fmt.ci(c.classes[k].recall.wilson?.[0], c.classes[k].recall.wilson?.[1], 3)}`, `${n3(c.classes[k].precision.rate)} ${fmt.ci(c.classes[k].precision.wilson?.[0], c.classes[k].precision.wilson?.[1], 3)}`, c.classes[k].verdict090])));
  L.push(`The cues fire on ${pc(c.askRate, 1)} of the items. Triggers by webhook, event or poll (${c.classes.trigger.truthPositives} items) are a declared volume and are outside "any".`, '',
    `**Part B, E8 and runbook** (tiny n by construction: ${b.e8.recall.declared} and ${b.runbook.recall.declared} declared requirements, those of PREREG-NEED-V1 §3.2):`, '',
    ...tbl(['bed', 'declared requirement', 'typed field found', 'word cue fires on the bed text', 'typed evidence'],
      ['e8', 'runbook'].flatMap(id => (b[id].declared ?? []).map(cl => [id, cl, tick(b[id].perClass?.[cl]?.typed), tick(b[id].perClass?.[cl]?.cueOnFullText), (b[id].typed?.[cl]?.evidence ?? []).slice(0, 2).map(code).join('; ') || 'none']))));
  L.push(`E8's text is ${code('spec/SPEC-E.md')} (${b.e8.text.chars.toLocaleString('en-US')} characters); runbook's is the generated prompt plus ticket, runbook and inventory of dev seed 601 at d3 (${b.runbook.text.promptChars.toLocaleString('en-US')} + ${b.runbook.text.inputChars.toLocaleString('en-US')} characters). Recall of the declared requirements: E8 typed ${n2(b.e8.recall.typed)}, cues ${n2(b.e8.recall.cueFullText)}; runbook typed ${n2(b.runbook.recall.typed)}, cues ${n2(b.runbook.recall.cueFullText)}. The cues also fire on every class not declared (all four fire on both beds), so on a long specification the cue guard asks about everything.`, '');
  if (nd('e8').length || nd('runbook').length) {
    L.push('Typed fields that evidence a requirement the preregistered candidate list does not name:', '',
      ...tbl(['bed', 'class', 'typed evidence'], ['e8', 'runbook'].flatMap(id => (b[id].typedNotDeclared ?? []).map(x => [id, x.class, x.evidence.map(code).join('; ')]))));
  }
  L.push('**Reading.**',
    `- **The word cues cannot be the guard.** On corpus descriptions their recall of "any hard requirement" is ${pc(any.recall.rate, 1)} (95% interval ${fmt.ci(any.recall.wilson[0], any.recall.wilson[1], 3)}); by class: human ${pc(c.classes.human.recall.rate)}, wait ${pc(c.classes.wait.recall.rate)}, schedule ${pc(c.classes.schedule.recall.rate)}, effects ${pc(c.classes.effects.recall.rate, 1)}. ${allBelow ? 'Every class is under the 0.9 line (and under RX6\'s original 0.95), so by the preregistered rule the guard asks instead of inferring.' : 'Not every class is under the 0.9 line; see the table.'} Where a cue does fire it is mostly right for effects (precision ${pc(c.classes.effects.precision.rate)}) and poor for human and wait (${pc(c.classes.human.precision.rate)} and ${pc(c.classes.wait.precision.rate)}).`,
    `- The truth side matters: ${pc(c.classes.effects.baseRate)} of these automations write or call something external, so "effects with authority" read from the graph is nearly universal and says little about which jobs need a workflow. A typed field declared by the owner is the only usable guard input, and the declared set has to be right.`,
    `- **Typed fields are better evidence than prose, and they show the candidate lists are incomplete.** E8's typed declarations evidence ${list(nd('e8'))} beyond the requirements PREREG lists for it, and runbook's evidence ${list(nd('runbook'))} beyond its two.${e8NoSched ? ` The search of E8's family, schemas and systems for timer, deadline or schedule declarations (${e8Sched.searched.join(', ')}) found none, so that declared requirement rests on the spec text alone.` : e8Sched ? ` E8's declared "schedule" is found by that search (${e8Sched.searched.join(', ')}) as ${e8Sched.evidence.slice(0, 2).map(code).join(' and ')}${e8Sched.note ? `: ${e8Sched.note}` : ''}.` : ''} [I] Add human approval to e8 and durable wait to runbook before D5 is used as a guard test, and decide whether compensation is a fifth class (the engine-support flag already names it).`,
    '- Corpus descriptions are one sentence and the guard will read job specifications, so Part A is a lower bound for real specifications; Part B shows the opposite failure (cues fire on everything in a 20K-character spec). Neither supports inferring requirements from text.', '',
    `**Limits.** Corpus truth is graph structure, not what the author meant; the ${c.items} originals are automations people chose to build; the cue-to-class mapping uses only words already in code; Part B has ${b.e8.recall.declared + b.runbook.recall.declared} declared requirements in total.`, '',
    ...sourceLines([c.source.path, 'experiments/library/index.mjs', 'src/construction-objective.mjs', 'beds/ebed/e8/spec/SPEC-E.md', 'beds/ebed/e8/index.mjs', 'beds/runbook/index.mjs'], ctx), `(${code('research/corpus-20261006/items.jsonl')} is git-ignored and rebuilt from the committed ${code('items.jsonl.gz')} by ${code('scripts/unpack.mjs')}.)`, '');
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- D6
function secD6(d, ctx) {
  const L = [], s = d.summary, bs = d.builderSessions, m = Object.fromEntries(d.agentSessions.byModelEra.map(x => [x.key, x]));
  const opusB = bs.sessions.filter(r => r.model.includes('opus')), haikuB = bs.sessions.filter(r => r.model.includes('haiku'));
  const opPre = m['claude-opus-5-5 | pre-flag'], opPost = m['claude-opus-5-5 | post-flag'], soPost = m['claude-sonnet-5-5 | post-flag'], hkPre = m['claude-haiku-5-5 | pre-flag'], hkPost = m['claude-haiku-5-5 | post-flag'];
  const think = opusB.map(r => r.thinkingTokens).filter(Number.isFinite);
  const flipped = d.meterImpact.filter(i => i.p5.labelFlips > 0 || i.p1h.labelFlips > 0), moved = d.meterImpact.filter(i => i.p5.topChanges > 0 || i.p1h.topChanges > 0);
  const recMin = Math.min(...d.agentSessions.byModelEra.map(x => x.meanRecordedOutputTokens)), recMax = Math.max(...d.agentSessions.byModelEra.map(x => x.meanRecordedOutputTokens));
  const eraRatios = [opPre.ratioReportedOverEra, opPost.ratioReportedOverEra];
  const headChanged = d.meterImpact.filter(i => !i.reported.headlineUnlabelled && [i.p5, i.p1h].some(x => !x.headlineUnlabelled && x.headlineLabel !== i.reported.headlineLabel));
  const headUnlabelled = d.meterImpact.filter(i => i.reported.headlineUnlabelled);
  const le = d.launchEnv;
  const gate = s.meterGate;
  L.push('## D6. Cost-meter delta: CLI-reported against token re-priced', '',
    `**Grade: LEGACY/dev.** **Question:** the CLI books its own figure; the v1 label factory re-prices every row from recorded tokens with one pinned table (${code(d.priceTable)}). How far apart are they on archived agent rows (${d.agentSessions.count} sessions with recorded stream usage)? **Price variants.** p5 = the pinned table with 5-minute cache writes and the session's aggregate tokens at one tier (what ${code('label-run.priceSession')} does for a session with stream usage only); p1h = the same with cache writes at the 1-hour rate (2 x input); **era rate** = p1h for sessions before ${code('FORCE_PROMPT_CACHING_5M=1')} entered the policy (commit ${code(d.cacheFlag.commit)}, ${d.cacheFlag.at}: P1 and the C0 dev round) and p5 after it (the JIT streams, which began 2026-10-08 23:36 UTC). The archive can confirm the cache rate only for the C0 builder sessions below; the post-flag rate is the policy's own account.`, '');
  L.push('**Check 1: builder sessions** (C0 dev round, before the flag), where the CLI\'s final usage (output tokens, 5-minute and 1-hour cache split) is recorded:', '',
    ...tbl(['session', 'model', 'CLI-reported', 'pinned table, 5m writes', 'pinned table, billed 1h rate', 'reported / 5m', 'reported / billed rate', 'output tokens: final (stream)'],
      bs.sessions.map(r => [r.label, r.model.replace('claude-', ''), usd(r.reportedUsd, 4), usd(r.p5Usd, 4), r.billedRateUsd === r.billedRateLowTierUsd ? usd(r.billedRateUsd, 4) : `${usd(r.billedRateLowTierUsd, 4)} to ${usd(r.billedRateUsd, 4)}`, n3(r.ratioReportedOverP5), r.billedRateUsd === r.billedRateLowTierUsd ? n3(r.ratioReportedOverBilledRate) : `inside the bracket: ${tick(r.reportedInBilledRateBracket)}`, `${r.outputTokensFinal.toLocaleString('en-US')} (${r.outputTokensStreamUsage})`])));
  L.push('**Check 2: agent task sessions**, where only the stream aggregate is recorded, per model and era (sums over sessions; "implied output" is the output tokens the gap between the reported figure and the era-rate re-price would need, defined for single-tier models only):', '',
    ...tbl(['model', 'era', 'sessions', 'reported', 'p5', 'p1h', 'era rate', 'reported / p5', 'reported / era rate', 'mean recorded output tokens', 'median implied output tokens'],
      d.agentSessions.byModelEra.map(x => { const [mo, era] = x.key.split(' | '); return [mo.replace('claude-', ''), era, x.sessions, usd(x.reportedUsd, 2), usd(x.p5Usd, 2), usd(x.p1hUsd, 2), usd(x.pEraUsd, 2), n2(x.ratioReportedOverP5), n2(x.ratioReportedOverEra), x.meanRecordedOutputTokens, mo.includes('haiku') ? 'n/a (two tiers)' : x.medianImpliedOutputTokensEra.toLocaleString('en-US')]; })));
  L.push('**Check 3: direct calls** (P1; recorded tokens carry no cache fields). The output-token share of the reported cost is ' + d.directCalls.map(x => `${x.mode} ${pc(x.outputShareOfReported)}`).join(', ') + '; the rest is prompt cache writes that the row cannot show.', '',
    '**Check 4: does the meter move the labels?** Agent modes re-priced row by row under each variant (p5, p1h), labels recomputed over the 27-cell grid and compared with the reported meter:', '',
    ...tbl(['job', 're-priced modes', 'L_today: headline best mode (reported)', 'p5: label flips / best-mode changes (comparable cells)', 'p5 headline', 'p1h: label flips / best-mode changes (comparable cells)', 'p1h headline', 'unlabelled cells (reported / p5 / p1h)', 'L_ceiling (reported / p5 / p1h headline)'],
      d.meterImpact.map(i => [code(i.job), i.repricedModes.join(', '), headText(i.reported), `${i.p5.labelFlips} / ${i.p5.topChanges} (${i.p5.comparableCells})`, headText(i.p5), `${i.p1h.labelFlips} / ${i.p1h.topChanges} (${i.p1h.comparableCells})`, headText(i.p1h),
        `${i.reported.unlabelledCells} / ${i.p5.unlabelledCells} / ${i.p1h.unlabelledCells} of ${i.cells}`,
        i.ceiling ? [i.ceiling.reported, i.ceiling.p5, i.ceiling.p1h].map(headText).join(' / ') : 'same'])));
  const haikuInBracket = haikuB.filter(r => r.reportedInBilledRateBracket).length, haikuExact = haikuB.filter(r => r.exactAtBilledRate).length;
  L.push('**Reading.**',
    `- **The price formula is right; before the flag the CLI billed cache writes at the 1-hour rate.** For the ${opusB.length} Opus builder sessions the pinned table with 1-hour writes reproduces the CLI figure to the cent (reported / billed rate = ${list([...new Set(opusB.map(r => n3(r.ratioReportedOverBilledRate)))])}); with the 5-minute rate the table is ${pc(1 - 1 / s.builderRatioOverP5['claude-opus-5-5'])} too low. Every cache write in these sessions was a 1-hour write. Archived dollars from before the flag and new ones are therefore not comparable (the policy says so too): one more reason LEGACY rows are never pooled.`,
    `- **Haiku needs per-request tiers.** The aggregate convention prices a whole session at the >100K prompt tier because its tokens add up past 100K, but each request is far smaller. For the ${haikuB.length} Haiku builder sessions the reported figure falls inside [lowest tier, aggregate tier] in ${haikuInBracket} and equals the lowest-tier price exactly in ${haikuExact} (a session whose requests all stayed under 100K); the aggregate-tier price is up to ${n2(1 / Math.min(...haikuB.map(r => r.ratioReportedOverBilledRate)))} times the reported figure. For Haiku agent sessions the reported total is ${n2(hkPre.ratioReportedOverEra)} times the era-rate re-price before the flag and ${n2(hkPost.ratioReportedOverEra)} times after it: the overstatement from aggregate tiering and the missing output tokens (next bullet) roughly cancel, so the Haiku totals look right for the wrong reasons.`,
    `- **Stream usage cannot see output tokens.** The builder records show ${Math.min(...bs.sessions.map(r => r.outputTokensFinal)).toLocaleString('en-US')} to ${Math.max(...bs.sessions.map(r => r.outputTokensFinal)).toLocaleString('en-US')} output tokens in the CLI's final usage against ${Math.min(...bs.sessions.map(r => r.outputTokensStreamUsage))} to ${Math.max(...bs.sessions.map(r => r.outputTokensStreamUsage))} in ${code('streamUsage')}; agent task sessions record ${recMin} to ${recMax} on average. Re-pricing an Opus agent session from its stream usage therefore lands ${n2(opPre.ratioReportedOverEra)} times (before the flag, at the 1-hour rate) or ${n2(opPost.ratioReportedOverEra)} times (after it, at the 5-minute rate) below the reported figure, and Sonnet ${n2(soPost.ratioReportedOverEra)} times after it. The gaps imply about ${opPre.medianImpliedOutputTokensEra.toLocaleString('en-US')} (Opus before), ${opPost.medianImpliedOutputTokensEra.toLocaleString('en-US')} (Opus after) and ${soPost.medianImpliedOutputTokensEra.toLocaleString('en-US')} (Sonnet after) unrecorded output tokens per session [I]: stable across eras and of the order of the ${Math.round(Math.min(...think) / 1000)}K to ${Math.round(Math.max(...think) / 1000)}K thinking tokens the Opus builder sessions report.`,
    `- **The meter decides some labels.** Re-pricing the agent modes moves the best mode in ${moved.length} of ${d.meterImpact.length} jobs (${list(moved.map(i => i.job))}) and flips a NEED label in some cell of ${flipped.length} (${list(flipped.map(i => i.job))}), counting only cells that are labelled under both meters; at the headline cell it changes the L_today headline label of ${list(headChanged.map(i => `${i.job} (${i.reported.headlineTop}, ${i.reported.headlineLabel} to ${i.p5.headlineTop}, ${i.p5.headlineLabel} under p5)`))}. ${headUnlabelled.length ? `The headline cell is unlabelled under the reported meter for ${list(headUnlabelled.map(i => `${i.job} (${i.reported.headlineUnlabelled})`))}, so it says nothing about the meter there; ` : ''}${d.meterImpact.reduce((a, i) => a + i.reported.unlabelledCells, 0)} of the ${d.meterImpact.length * 27} job-by-cell cells are unlabelled under the reported meter and are left out of the flip and change counts. Agent-O costs ${n2(Math.min(...eraRatios))} to ${n2(Math.max(...eraRatios))} times less under the era-rate re-price, which is what moves its cells. A mode comparison on two meters is an accounting comparison.`,
    `- **The meter is now a gate, not a recommendation.** ${code('summary.meterGate')} in ${code('diagnostics.json')} is **${gate.status}**${gate.reasons.length ? ` (${gate.reasons.map(r => code(r.code)).join(', ')}): ${gate.reasons.map(r => r.detail).join('; ')}` : ''}. ${code('messageUsageOf')} (${code('experiments/c0/construct.mjs')}) reads per-message ${code('assistant.message.usage')} lines from the session transcript, the same kind of line that produced the archived ${code('streamUsage')}, so ${code('label-run.priceSession')} would book the same under-priced output as ${code('measured')}: the stage cap is safe (it meters max(reported, re-priced)), but utility would use the low figure and the 30%-imputed rule would never see the shortfall. ${code('label-run.mjs')} therefore (1) refuses to start a paid stage with an agent arm while the gate is set and no passing verification record is on file (clear it with ${code('node experiments/need-router/meter-gate-cli.mjs --verify <transcript>... --write research/need-router-20261014/analysis/m0/meter-verification.json')} on at least ${gate.rule.minVerifySessions} saved CLI transcripts), and (2) checks every agent session it prices: per-message output tokens within ${pc(gate.rule.outputTolerance)} of the CLI's final result usage; if the lines are snapshots, the output tokens they miss are priced from the final usage and the session is accepted as measured (flagged ${code('outputFromFinal')}) only if the result lands within ${pc(gate.rule.priceBand)} of the CLI's own figure; otherwise, or with no final usage, it is booked at the reported figure with the shortfall imputed and flagged ${code('meterUnverified')}. **The gate fails closed**: ${code('label-run.mjs')} reads it from the committed HEAD blob of ${code('diagnostics.json')} (as it reads the preregistration) and refuses an agent stage while the working-tree file differs from that blob; with no gate to read (a missing, unparseable or partial file, or a status other than clear or block-until-verified) it refuses too, unless the owner's waiver is committed as ${code('analysis/m0/meter-gate-waiver.json')} (schema ${code('need-meter-gate-waiver/1')}, by owner, with a reason and a date) and is then recorded in ${code('report.deviations')}. ${code('run.mjs')} refuses ${code('--only')} against ${code('analysis/m0')}, and a subset written elsewhere is marked ${code('partial')}.`, '',
    `- **The launch environment decides the cache-write rate, and the launch command in DESIGN §7 sets none.** The pinned table prices cache writes at the 5-minute rate (1.25 x input) on the policy's account that ${code('FORCE_PROMPT_CACHING_5M=1')} is in force. The gateway's CLI provider sets it by default (its DEFAULT_CHILD_ENV), but an executor session keeps only what the run's shell sets (${code('src/executors/claude-code.mjs')}, executorEnv), and the launch command (an ${code('env -i')} with PATH, HOME, TMPDIR, LANG, TERM and the owner's CLI auth variable) sets no cache switch [M, code read]. ${le ? `[M; measured by ${code('launch-env.mjs')} and committed as ${code('analysis/m0/launch-env.json')} (sha256 ${code(le.source.sha256.slice(0, 16))}, measured ${le.measuredAt}), which lists every transcript by the first 16 hex of its sha256; run.mjs reads that file and opens no transcript] Of the ${le.summary.transcripts} CLI transcripts under ${code('/var/tmp/foundry-work')} modified after the flag (${le.after}), ${le.summary.withFinalUsage} have a final usage record (${Object.entries(le.summary.byModel).map(([m, x]) => `${x.sessions} ${m.replace('claude-', '').replace('-5-5', '')}`).join(', ')}; ${le.summary.skipped} have none: ${Object.entries(le.summary.skippedReasons).map(([r, n]) => `${n} with ${r.replace(/^no /, 'no ')}`).join(', ')}). Every cache write in ${Object.values(le.summary.byModel).reduce((a, x) => a + x.allWritesOneHour, 0)} of ${Object.values(le.summary.byModel).reduce((a, x) => a + x.withCacheWrites, 0)} sessions with cache writes is recorded as a 1-hour write. The CLI's reported cost equals the pinned table with 1-hour writes (2 x input) to within 1% for ${Object.entries(le.summary.byModel).map(([m, x]) => `${x.exact1h} of ${x.sessions} ${m.replace('claude-', '').replace('-5-5', '')}`).join(', ')} sessions, and with 5-minute writes for ${Object.values(le.summary.byModel).reduce((a, x) => a + x.exact5m, 0)} of ${le.summary.withFinalUsage} (Haiku is priced at its lowest tier here, so a Haiku session whose requests crossed 100K tokens misses either way). Re-pricing a session with the 5-minute rate lands at a median ${Object.entries(le.summary.byModel).map(([m, x]) => `${n2(x.medianRatio5mOverReported)} (${m.replace('claude-', '').replace('-5-5', '')})`).join(', ')} of the reported figure.` : `No launch-environment measurement is committed (${code('analysis/m0/launch-env.json')}, written by ${code('launch-env.mjs --write')}), so what the CLI bills in the executor sessions of this container is not stated here.`} Unless the NL0 launch sets ${code('FORCE_PROMPT_CACHING_5M=1')} in its shell, or the table is revised by a recorded deviation, the gate's 10% price band rejects real agent sessions and their cells are imputed and left unlabelled. ${code('meter-gate-cli.mjs --verify')} reports this per session (${code('cacheWrite1hShare')} and a hint).`, '',
    '**Limits.** The gate is built from archived evidence (the 8 C0 builder sessions and the per-model-era ratios); the verification tool has run only on synthetic transcripts in the tests, so the first real transcript will be a paid agent smoke row. Stream aggregates cannot say which requests crossed 100K; "implied output" is an inference that assumes each era\'s cache rate held for every session; the cache rate of the post-flag sessions is the policy\'s account, not something these rows show; the JIT interpreter traces can hold several sessions per task. The direct-call rows cannot be re-priced at all.', '',
    ...sourceLines([...jobSources(ctx.r), ...d.sources.map(x => x.path), 'research/need-router-20261014/archive/c0-dev/constructions.jsonl', 'policy/models.json'], ctx));
  return L;
}

// ---------------------------------------------------------------------------------------------------------------------------- report
export function renderReport(r) {
  const sha = Object.fromEntries(r.inputs.legacySources.map(s => [s.path, s.sha256.slice(0, 16)]));
  for (const k of ['d0', 'd1', 'd5', 'd6']) for (const s of (r[k]?.sources ?? [])) if (s.path) sha[s.path] = s.sha256.slice(0, 16);
  if (r.d5?.corpus?.source) sha[r.d5.corpus.source.path] = r.d5.corpus.source.sha256.slice(0, 16);
  if (r.d2?.nversion?.source) sha[r.d2.nversion.source.path] = r.d2.nversion.source.sha256.slice(0, 16);
  const ctx = { r, sha };
  const L = [];
  L.push('# M0 diagnostics D0-D6: $0 checks on archived rows and the feature census', '',
    '*Need router v1, 2026-10-14. Generated by `experiments/need-router/diagnostics/run.mjs --report` from `analysis/m0/diagnostics.json`; no model call, no network.*', '',
    '**Evidence grade.** Development. D2, D3, D4 and D6 read **LEGACY** rows: archived P1, C0-dev and JIT stream runs that predate the need-router protocol (single draw or K = 1, dev or inspected seeds, P1 timeouts booked at $0, P1 and C0-dev billed with 1-hour cache writes). They are never pooled with new labels (DESIGN §2). D0, D1 and D5 read the feature census, the preregistered job table and the corpus overlay. Nothing here is a held-out result or a router result: these are checks on the benchmark, run before any label is paid for.', '');
  L.push('## Findings at a glance', '');
  const glance = [];
  if (r.d0) { const a = r.d0.primary.find(p => p.k === 3).design.stats, b = r.d0.primary.find(p => p.k === 5).design.stats; glance.push(['D0', 'NR-knn neighbours, L8', `L8 ${a.l8Trips || b.l8Trips ? 'trips' : 'does not trip'}: ${a.dominant}/${a.queries} (k=3) and ${b.dominant}/${b.queries} (k=5) held-out entries have one-cluster neighbours (${pc(a.chanceDominantShare)} and ${pc(b.chanceDominantShare)} at chance); the plurality cluster is W for ${b.modalClusterCounts.W ?? 0}/${b.queries} at k=5`]); }
  if (r.d1) { const s = r.d1.summary.router, m = r.d1.summary.maxExample; glance.push(['D1', 'tokens alone reproduce the table?', `${s.reproducedN1 || s.reproducedN10 ? 'In part' : 'No'}. Best threshold on the router feature: balanced accuracy ${n3(s.balancedAccuracyN1)} at N=1 (errors ${list(s.errorsN1)}) and ${n3(s.balancedAccuracyN10)} at N=10 (errors ${list(s.errorsN10)}); on max-example tokens ${n3(m.balancedAccuracyN1)} and ${n3(m.balancedAccuracyN10)} (errors ${list(m.errorsN10)} at N=10). A size rule is a strong baseline`]); }
  if (r.d2) { const p = r.d2.primary; glance.push(['D2', 'co-failure, agent-H and static-b1h (records dev, n=24)', `lift ${n2(p.lift)} [${n2(p.liftCI[0])}, ${n2(p.liftCI[1])}], p ${n2(p.pPermutation)}: no excess co-failure, low power; the compiled solvers of the N-version probe do fail together`]); }
  if (r.d3) { const s = r.d3.summary; glance.push(['D3', 'post-hoc against ex-ante signals', `No reliable instance-level signal of either kind (median AUC ${n2(s.primary.medianAucPostHoc)} post-hoc, ${n2(s.primary.medianAucExAnte)} ex-ante); workflows' own verdict passed ${s.selfVerdict.falsePass} of ${s.selfVerdict.oracleFailures} oracle failures (${s.groupsScored} of ${s.groups} scoreable groups; ${s.groupsExcluded} JIT and static groups not scored)`]); }
  if (r.d4) {
    const s = r.d4.summary, p1 = r.d4.jobs.find(j => j.job === 'p1-records'), live = r.d4.jobs.length - s.vacuousJobs.length;
    glance.push(['D4', 'tolerance fragility', `${s.gainedAtDouble} failing rows pass at x2 tolerance and ${s.lostAtHalf} passes fail at x0.5; ${s.fragileJobs.length} of the ${live} jobs with a workflow arm in L_today have a flipping label (${list(s.fragileJobs)}; ${list(s.vacuousJobs)} ${s.vacuousJobs.length > 1 ? 'are' : 'is'} vacuous there); ${s.unlabelledCells} of ${s.cells} job-by-cell cells are unlabelled (more than 30% of a contending mode's dollars imputed) and left out; the best mode changes in ${s.topChangedCells} of the ${s.labelledCells} labelled cells. P1's hand workflow is a ceiling arm with its ${usd(r.inputs.p1Authoring?.usd, 2)}${r.inputs.p1Authoring?.lowerBound ? '+' : ''} authoring charged: ${p1?.ceiling ? `its headline cell is ${p1.ceiling.headline['1'].unlabelled ? `unlabelled (${p1.ceiling.headline['1'].unlabelled}) in L_ceiling` : `${p1.ceiling.headline['1'].label} (${p1.ceiling.headline['1'].top} best) in L_ceiling`}, and L_ceiling says workflow in ${p1.ceiling.labelCounts.workflow} of its ${p1.ceiling.grid.labelled} labelled cells` : 'no ceiling view'}; L_today has no workflow arm for P1`]);
  }
  if (r.d5) { const s = r.d5.summary; glance.push(['D5', 'guard recall (RX6-lite)', `Word cues recall ${pc(s.recallAny, 1)} of graph-declared requirements on ${s.corpusItems} corpus descriptions (${s.guardAsksInsteadOfInferring.length === 4 ? 'every class' : s.guardAsksInsteadOfInferring.join(', ')} under 0.9: the guard asks, it does not infer); typed fields evidence ${n2(s.e8TypedRecall)} of E8's and ${n2(s.runbookTypedRecall)} of runbook's declared requirements`]); }
  if (r.d6) { const s = r.d6.summary, e = s.byModelEra; glance.push(['D6', 'CLI-reported against re-priced', `Opus agent sessions: reported is ${n2(e['claude-opus-5-5 | pre-flag'].ratioReportedOverEra)}x (before the 5-minute cache flag) and ${n2(e['claude-opus-5-5 | post-flag'].ratioReportedOverEra)}x (after) the pinned-table re-price from stream usage, because output tokens are not recorded; builder sessions with full usage reproduce exactly at the 1-hour cache-write rate; the meter moves the best mode in ${s.jobsAffected.length} of ${r.d6.meterImpact.length} jobs; the cost-meter gate is ${s.meterGate.status} (label-run refuses a paid agent stage until a verification record exists)`]); }
  L.push(...tbl(['', 'check', 'answer'], glance));
  L.push('## What these numbers change in the plan', '', 'Recommendations are mine ([I]); each is backed by the section named.', '');
  const recGain = r.d4?.jobs.filter(j => j.oracle === 'records').map(j => j.rowFlips.gainedShare);
  const plan = [];
  if (r.d1) { const tk = id => r.d1.featureRows.find(x => x.id === id)?.tokens, wf = r.d1.jobs.filter(j => j.n10.class === 'workflow'), sm = wf.reduce((a, j) => (tk(j.id) < tk(a.id) ? j : a)); plan.push(`**Check r0-pad's margin before NL0 (D1).** On the router's feature it sits at ${thr(tk('r0-pad'))} tokens against ${thr(tk(sm.id))} for ${sm.id}, the smallest N = 10 workflow job (${n2(tk('r0-pad') / tk(sm.id))} times), so it breaks a token threshold, but on the max-example measure it is below that job. The margin is thin and rests on the example seeds; confirm it when the generator is final, and expect incident to carry the large-no-workflow test either way.`); }
  if (r.d0) plan.push('**Keep NR-knn secondary and run L8 on the real TRAIN jobs (D0).** It does not trip on the census, but neighbours lean on cluster W and eight queries decide little.');
  if (r.d2 && r.d3) plan.push(`**Do not use disagreement as a verifier on faith (D2) and keep self-check credit off until F11 data exist (D3).** One pair shows no excess co-failure, compiled solvers do fail together, and workflow self-verdicts passed ${r.d3.summary.selfVerdict.falsePass} of ${r.d3.summary.selfVerdict.oracleFailures} oracle failures.`);
  if (r.d4) plan.push(`**Run the tolerance recompute on every job with a numeric oracle (D4), charge every build, and read only labelled cells.** In the records jobs ${pc(Math.min(...recGain))} to ${pc(Math.max(...recGain))} of failures pass at double tolerance; the L_today class label held in ${r.d4.summary.jobs - r.d4.summary.vacuousJobs.length - r.d4.summary.fragileJobs.length} of the ${r.d4.summary.jobs - r.d4.summary.vacuousJobs.length} jobs that have a workflow arm there; the best mode changed in ${r.d4.summary.jobsWithTopChange.length} jobs. A hand-written or frontier-built workflow is a ceiling arm and its authoring is a build cost (P1: ${usd(r.inputs.p1Authoring?.usd, 2)}+): left out, it made P1 look like a workflow job. ${r.d4.summary.unlabelledCells} of ${r.d4.summary.cells} job-by-cell cells rest on imputed dollars (P1's timeouts charged at their bound) and carry no label.`);
  if (r.d5) plan.push('**Treat word cues as "ask" only, and extend the typed candidate lists (D5).** Add human approval (and compensation) to e8 and durable wait to runbook where the beds already type them.');
  if (r.d6) plan.push(`**Clear the cost-meter gate before NL0 (D6).** It is ${r.d6.summary.meterGate.status}: \`label-run.mjs\` will not start a stage with an agent arm (NL0 has five) until \`meter-gate-cli.mjs --verify\` has passed on saved CLI transcripts, and meanwhile prices any agent session whose per-message output tokens differ from the final usage from the final usage if the CLI's own figure corroborates it, else books it at the reported figure as imputed. Price Haiku per request, and never mix dollars from before and after the 5-minute cache flag.`);
  plan.forEach((t, i) => L.push(`${i + 1}. ${t}`));
  L.push('', '## Inputs', '',
    'The rescued archive (`research/need-router-20261014/archive/`, see its `MANIFEST.json`) holds byte copies of the git-ignored P1 and C0-dev JSONL; the JIT streams are the committed exports under `research/jit-20261008/runs/`. The diagnostics read the copies, never the ignored originals.', '',
    ...tbl(['job', 'kind', 'family', 'paired units', 'modes', 'rows (all)', 'build costs'], r.inputs.jobs.map(j => [code(j.id), j.kind, j.family, j.units, j.modes.join(', '), `${j.rows} (${j.allRows})`, j.builds.length ? j.builds.map(b => `${b.mode} ${usd(b.usd, 2)}${b.lowerBound ? '+' : ''}`).join(', ') : 'none'])),
    ...(r.inputs.jobs.some(j => (j.harvest?.notes?.length ?? 0) || (j.harvest?.dropped?.length ?? 0) || (j.dropped?.length ?? 0)) ? ['Pairing and harvest notes (what the stream harvest dropped before this loader paired the modes again, and the builds it charged outside the stream; the table counts paired rows, with every row in brackets):', '',
      ...r.inputs.jobs.flatMap(j => [...(j.harvest?.dropped ?? []).map(x => `- ${code(j.id)}: mode ${x.mode} dropped by the harvest (${x.tasks} tasks, under half the units)`), ...(j.harvest?.notes ?? []).map(x => `- ${code(j.id)}: ${x}`), ...(j.dropped ?? []).map(x => `- ${code(j.id)}: mode ${x.mode} dropped by pairing (${x.units} rows)`)]), ''] : []),
    ...(r.inputs.notes.length ? ['Notes (inputs that could not be loaded, jobs that yielded no rows, rows whose unobserved cost was imputed):', ...r.inputs.notes.map(x => `- ${x}`), ''] : []),
    ...tbl(['file', 'sha256 (16)', 'bytes'], r.inputs.legacySources.filter(s => !s.path.includes('/runs/')).map(s => [code(s.path), code(s.sha256.slice(0, 16)), s.bytes])),
    `Plus ${r.inputs.legacySources.filter(s => s.path.includes('/runs/')).length} JIT stream result files under ${code('research/jit-20261008/runs/')} (each with its sha256 in ${code('diagnostics.json')}, ${code('inputs.legacySources')}).`, '',
    `P1 hand-workflow authoring is charged: ${r.inputs.p1Authoring ? `${usd(r.inputs.p1Authoring.usd, 2)}${r.inputs.p1Authoring.lowerBound ? ' at least (the Opus agent time that wrote the workflow is unpriced)' : ''}, the records-v3 development calls (${r.inputs.p1Authoring.calls.toLocaleString('en-US')} of them), to each of ${r.inputs.p1Authoring.modes.join(' and ')} in full. Source: ${r.inputs.p1Authoring.source}. \`research/core-20261006/REPORT.md\` does not contain the figure; it calls the workflow a hand-written ceiling` : 'no figure recorded'}. C0 construction costs and JIT compile and external build costs are charged as build rows too. Every workflow not written by the cheap builder (Haiku) is a ceiling arm (L_ceiling only, DESIGN §2): ${Object.entries(r.inputs.ceilingRule.byBuilder).filter(([b]) => r.inputs.ceilingRule.ceilingBuilders.includes(b)).map(([b, ms]) => `${ms.join(', ')} (${b})`).join('; ')}.`,
    ...(r.inputs.skippedStreams?.length ? ['', `Stream experiments under ${code('research/jit-20261008/runs/')} that no job definition names were **not opened**: ${r.inputs.skippedStreams.map(x => code(x.experiment)).join(', ')}.`] : ['', `Every stream experiment under ${code('research/jit-20261008/runs/')} is named by a job definition (none was skipped); an experiment no definition names is never opened.`]), '');
  if (r.d0) L.push(...secD0(r.d0, ctx));
  if (r.d1) L.push(...secD1(r.d1, ctx));
  if (r.d2) L.push(...secD2(r.d2, ctx));
  if (r.d3) L.push(...secD3(r.d3, ctx));
  if (r.d4) L.push(...secD4(r.d4, ctx));
  if (r.d5) L.push(...secD5(r.d5, ctx));
  if (r.d6) L.push(...secD6(r.d6, ctx));
  L.push('## Not done, and what could be wrong', '',
    '- **No new label and no router.** D0 to D6 are checks on the benchmark and its inputs; none scores a router.',
    '- **JSONL only was rescued.** [note] The SQLite model journals of P1 and C0-dev (17 to 22 MB each, raw prompts and outputs) and the logs stay under the git-ignored `experiments/runs/`. Per-request usage that may sit in the P1 journal (it would settle D6\'s tier question for P1) was not read.',
    '- **Class assignment of LEGACY modes is an assumption** (hand and Foundry workflows, static solvers and JIT count as workflow). JIT interprets first and compiles later, which is not the v1 workflow mode. Only workflows written by Haiku are L_today; the hand-written P1 workflow, the Opus-built C0 workflows and the Opus- and Sonnet-compiled JIT arms are ceiling arms (L_ceiling only), the Sonnet case by decision (legacy.mjs).',
    '- **D1\'s anchor-bed features (and D0\'s anchor sensitivity) are computed live** from `beds/need-*`, which were still being written; each bed\'s version and the hash of its module graph are recorded in `diagnostics.json` (`d1.anchorBeds.beds`) and `--check` reports a changed hash as "inputs moved". D1\'s other numbers use the committed census and job table. Re-run when those beds are frozen.',
    '- **D3 does not score the JIT and static arms** (`jit-HH`, `jit-OH`, `jit-SH`, `static-b1h`: their rows mix compile, shadow and adjudicator sessions); D6\'s gate is built from the C0 builder sessions and the per-model-era ratios, and its clearing path (`meter-gate-cli.mjs --verify` on saved CLI transcripts) has not met a real transcript yet.',
    '- **The meter-verification record is still read from the working tree**, not from HEAD (`meter-verification.json`): a hand-written passing record would clear a blocking gate, where the gate itself is read from the commit. It is made by `meter-gate-cli.mjs --verify` from saved transcripts and carries their hashes, but label-run does not re-derive it; committing it before a paid stage is the owner\'s check.',
    '- **RX6\'s hand-checked subsample was not done** [note] (100 descriptions checked by an annotator against their graphs, owner decision O5 of the 2026-10-07 review): D5 Part A takes the graph as truth.',
    '- **`replay-archived.json` and `.txt` were not regenerated.** `harvest.mjs` now tags its rows, fixed costs and report entries LEGACY with their source path; the committed replay outputs predate the tag until `replay.mjs --json` is re-run (that file is not part of this piece).',
    `- **D2 and D3 are small samples** (${r.d3 ? `${Math.min(...scoredGroups(r.d3).map(g => g.rowsDelivered))} to ${Math.max(...scoredGroups(r.d3).map(g => g.rowsDelivered))} delivered answers per scored arm` : 'D3 not run'}${r.d2 ? `; ${r.d2.primary.tasks} tasks for the primary co-failure pair` : ''}). Absence of a significant result is not evidence of absence.`,
    `- **D5 Part B** has ${r.d5 ? r.d5.e8AndRunbook.e8.recall.declared + r.d5.e8AndRunbook.runbook.recall.declared : 'few'} declared requirements in total; the cue-to-class mapping is mine and uses only words already in code.`,
    '- **Reproduce:** `node experiments/need-router/diagnostics/run.mjs --report` ([note] about 40 s; it refuses `--only` against `analysis/m0`, because label-run reads the cost-meter gate from that file; a subset needs another `--out`); `--check` compares a fresh run with the committed `diagnostics.json` and says whether it is current (exit 0), whether an input or the code moved so the file should be re-run (exit 2, the numbers may or may not have changed), or whether results differ with nothing of theirs moved (exit 1). D1 and D5 read files that are still changing (the anchor beds, `SPEC-E.md`, the E8 bed), so exit 2 is expected after their edits.', '',
    'Code fingerprints (first 16 hex of sha256): ' + Object.entries(r.code).map(([k, v]) => `${k} ${v}`).join('; ') + '.', '');
  return L.join('\n');
}
